return ['domain'=>'taxopress-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de-DE','project-id-version'=>'TaxoPress Pro 3.51.0','pot-creation-date'=>'2026-07-22T18:23:43+00:00','po-revision-date'=>'2026-07-22 18:32+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['TaxoPress Pro'=>'TaxoPress Pro','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','TaxoPress allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'TaxoPress ermöglicht es Ihnen, Tags, Kategorien und alle Ihre WordPress-Taxonomie-Begriffe zu erstellen und zu verwalten.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','License key'=>'Lizenzschlüssel','Status'=>'Status','Your license key provides access to updates and support.'=>'Ihr Lizenzschlüssel bietet Zugriff auf Updates und Support.','Activate License'=>'Lizenz aktivieren','Synonyms'=>'Synonyme','This feature allows you to associate additional words with each term. For example, "website" can have synonyms such as "websites", "web site", and "web pages".'=>'Diese Funktion ermöglicht es Ihnen, zusätzliche Wörter mit jedem Begriff zu verknüpfen. Zum Beispiel kann "website" Synonyme wie "websites", "web site" und "web pages" haben.','Linked Terms'=>'Verknüpfte Begriffe','This feature allows you to connect terms. When the main term or any of these terms are added to the post, all the other terms will be added also.'=>'Diese Funktion ermöglicht es Ihnen, Begriffe zu verbinden. Wenn der Hauptbegriff oder einer dieser Begriffe zum Beitrag hinzugefügt wird, werden auch alle anderen Begriffe hinzugefügt.','Shortcode Name'=>'Shortcode-Name','Add'=>'Hinzufügen','Enter the shortcode name without [ ] or parameters.'=>'Geben Sie den Shortcode-Namen ohne [ ] oder Parameter ein.','Search Block'=>'Suchblock','Search...'=>'Suche...','Search and select blocks.'=>'Blöcke suchen und auswählen.','Element tag'=>'Element-Tag','Add Element'=>'Element hinzufügen','New Element'=>'Neues Element','OpenAI is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'OpenAI ist ein externer Dienst, der Ihre Inhalte scannen und relevante Begriffe vorschlagen kann. %1sHier klicken für Details%2s.','False'=>'Falsch','True'=>'Wahr','This will automatically add new terms from the OpenAI service. Before use, please test carefully using the preview feature.'=>'Dies wird automatisch neue Begriffe aus dem OpenAI-Dienst hinzufügen. Bitte testen Sie vor der Verwendung sorgfältig mit der Vorschaufunktion.','Enable OpenAI'=>'OpenAI aktivieren','API Key'=>'API-Schlüssel','Enter your OpenAI API Key.'=>'Geben Sie Ihren OpenAI API-Schlüssel ein.','gpt-3.5-turbo'=>'gpt-3.5-turbo','gpt-4o-mini'=>'gpt-4o-mini','gpt-4o'=>'gpt-4o','chatgpt-4o-latest'=>'chatgpt-4o-latest','gpt-5'=>'gpt-5','gpt-5-mini'=>'gpt-5-mini','gpt-5-nano'=>'gpt-5-nano','o3-mini'=>'o3-mini','o1-mini'=>'o1-mini','o1'=>'o1','OpenAI Models'=>'OpenAI-Modelle','Some models availability depends on your subscription and access.'=>'Die Verfügbarkeit einiger Modelle hängt von Ihrem Abonnement und Zugriff ab.','Show Term Post Count'=>'Begriffspostanzahl anzeigen','This will show the number of posts attached to the terms.'=>'Dies zeigt die Anzahl der Beiträge an, die mit den Begriffen verbunden sind.','Cache Results'=>'Ergebnisse zwischenspeichern','By caching the results locally, new API requests will not be made unless the post title or content changes. This saves API usage.'=>'Durch das lokale Zwischenspeichern der Ergebnisse werden keine neuen API-Anfragen gestellt, es sei denn, der Titel oder der Inhalt des Beitrags ändert sich. Dies spart API-Nutzung.','OpenAI Prompt (Beta)'=>'OpenAI Prompt (Beta)','%1s Click here for prompt documentation. %2s'=>'%1s Klicken Sie hier für die Dokumentation zu Prompts. %2s','OpenAI Max Tokens'=>'OpenAI Max Tokens','Maximum tokens for OpenAI response. You can increase this when using {site} placeholder with many terms.'=>'Maximale Tokens für die OpenAI-Antwort. Sie können dies erhöhen, wenn Sie den {site} Platzhalter mit vielen Begriffen verwenden.','IBM Watson is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'IBM Watson ist ein externer Dienst, der Ihren Inhalt scannen und relevante Begriffe vorschlagen kann. %1sKlicken Sie hier für Details%2s.','This will automatically add new terms from the IBM Watson service. Before use, please test carefully using the preview feature.'=>'Dies fügt automatisch neue Begriffe aus dem IBM Watson-Dienst hinzu. Bitte testen Sie dies vor der Verwendung sorgfältig mit der Vorschaufunktion.','Enable IBM Watson'=>'IBM Watson aktivieren','API URL'=>'API-URL','Enter your IBM Watson API URL.'=>'Geben Sie Ihre IBM Watson API-URL ein.','Enter your IBM Watson API Key.'=>'Geben Sie Ihren IBM Watson API-Schlüssel ein.','This integration is no longer actively supported. If you still need to use it, you can enable it in the Legacy AI Sources settings.'=>'Diese Integration wird nicht mehr aktiv unterstützt. Wenn Sie sie weiterhin verwenden müssen, können Sie sie in den Einstellungen für Legacy AI-Quellen aktivieren.','Dandelion is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Dandelion ist ein externer Dienst, der Ihren Inhalt scannen und relevante Begriffe vorschlagen kann. %1sKlicken Sie hier für Details%2s.','This will automatically add new terms from the Dandelion service. Before use, please test carefully using the preview feature.'=>'Dies fügt automatisch neue Begriffe aus dem Dandelion-Dienst hinzu. Bitte testen Sie dies vor der Verwendung sorgfältig mit der Vorschaufunktion.','Enable Dandelion'=>'Dandelion aktivieren','API Token'=>'API-Token','Enter your Dandelion API Key.'=>'Geben Sie Ihren Dandelion API-Schlüssel ein.','API Confidence Value'=>'API Confidence Value','Choose a value between 0 and 1. A high value such as 0.8 will provide a few, accurate suggestions. A low value such as 0.2 will produce more suggestions, but they may be less accurate.'=>'Wählen Sie einen Wert zwischen 0 und 1. Ein hoher Wert wie 0.8 liefert einige präzise Vorschläge. Ein niedriger Wert wie 0.2 erzeugt mehr Vorschläge, aber diese sind möglicherweise weniger genau.','LSEG / Refinitiv is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'LSEG / Refinitiv ist ein externer Dienst, der Ihre Inhalte scannen und relevante Begriffe vorschlagen kann. %1sHier klicken für Details%2s.','This will automatically add new terms from the LSEG / Refinitiv service. Before use, please test carefully using the preview feature.'=>'Dies fügt automatisch neue Begriffe aus dem LSEG / Refinitiv-Dienst hinzu. Bitte testen Sie vor der Verwendung sorgfältig die Vorschaufunktion.','Enable LSEG / Refinitiv'=>'LSEG / Refinitiv aktivieren','Enter your LSEG / Refinitiv API Key.'=>'Geben Sie Ihren LSEG / Refinitiv API-Schlüssel ein.','Regular Expressions'=>'Reguläre Ausdrücke','Use Regular Expressions to change how Auto Terms analyzes your posts. This works for terms added when posts are saved or added via the "Schedule" feature.'=>'Verwenden Sie reguläre Ausdrücke, um zu ändern, wie Auto Terms Ihre Beiträge analysiert. Dies funktioniert für Begriffe, die hinzugefügt werden, wenn Beiträge gespeichert oder über die "Planen"-Funktion hinzugefügt werden.','Regex code'=>'Regex-Code','Example: <code>/\\b({term})\\b/i</code> will match the whole word while <code>/({term})/i</code> will match at any location even if it\'s part of another word. <code>{term}</code> will be replaced with the term name before the regex action.'=>'Beispiel: <code>/\\b({term})\\b/i</code> entspricht dem ganzen Wort, während <code>/({term})/i</code> an beliebiger Stelle übereinstimmt, selbst wenn es Teil eines anderen Wortes ist. <code>{term}</code> wird vor der Regex-Aktion durch den Begriffsnamen ersetzt.','Auto Terms successfully copied.'=>'Auto Terms erfolgreich kopiert.','Copy'=>'Kopieren','Hourly'=>'Stündlich','Daily'=>'Täglich','Primary Term Name'=>'Primärer Begriffname','Secondary Term Name'=>'Sekundärer Begriffname','Primary Term Taxonomy'=>'Primäre Begriffstaxonomie','Secondary Term Taxonomy'=>'Sekundäre Begriffstaxonomie','Primary Term Post Count'=>'Primäre Begriffsanzahl','Secondary Term Post Count'=>'Anzahl der Beiträge mit sekundärem Begriff','Add primary term to posts with secondary term'=>'Hauptbegriff zu Beiträgen mit sekundärem Begriff hinzufügen','Add secondary term to posts with primary term'=>'Sekundären Begriff zu Beiträgen mit Hauptbegriff hinzufügen','Delete Relationship'=>'Beziehung löschen','Taxonomy'=>'Taxonomie','Filter'=>'Filter','Error deleting linked term relationship.'=>'Fehler beim Löschen der verknüpften Begriffsbeziehung.','Linked terms deleted successfully.'=>'Verknüpfte Begriffe erfolgreich gelöscht.','Linked term deleted successfully.'=>'Verknüpfter Begriff erfolgreich gelöscht.','%d posts updated successfully.'=>'%d Beiträge erfolgreich aktualisiert.','0 post update.'=>'0 Beitrag aktualisiert.','No linked terms found.'=>'Keine verknüpften Begriffe gefunden.','Number of items per page'=>'Anzahl der Elemente pro Seite','This feature allows you to connect terms. When the primary or secondary term is added to a post, the other term can be added also.'=>'Mit dieser Funktion können Sie Begriffe verbinden. Wenn der Haupt- oder sekundäre Begriff zu einem Beitrag hinzugefügt wird, kann der andere Begriff ebenfalls hinzugefügt werden.','Search results for &#8220;%s&#8221;'=>'Suchergebnisse für &#8220;%s&#8221;','Search Terms'=>'Suchbegriffe','Description here.'=>'Beschreibung hier.','Start typing to choose existing terms.'=>'Beginnen Sie mit der Eingabe, um vorhandene Begriffe auszuwählen.','These terms are linked to the main term. When the primary or secondary term is added to a post, the other term can be added also.'=>'Diese Begriffe sind mit dem Hauptbegriff verknüpft. Wenn der Haupt- oder sekundäre Begriff zu einem Beitrag hinzugefügt wird, kann der andere Begriff ebenfalls hinzugefügt werden.','The superscript %1$s indicates the linked term being the primary term, while %2$s is shown when the linked term is the secondary term. You can delete the relationship and re-add it from your preferred term edit screen to make them the primary term.'=>'Die hochgestellte Zahl %1$s zeigt an, dass der verknüpfte Begriff der Hauptbegriff ist, während %2$s angezeigt wird, wenn der verknüpfte Begriff der sekundäre Begriff ist. Sie können die Beziehung löschen und sie von Ihrem bevorzugten Begriff-Bearbeitungsbildschirm erneut hinzufügen, um sie zum Hauptbegriff zu machen.','Term Synonyms'=>'Begriff Synonyme','Type the synonym name (comma-separated) and then click Enter or Return.'=>'Geben Sie den Synonymnamen (durch Kommas getrennt) ein und drücken Sie dann die Eingabetaste oder die Rücktaste.','If TaxoPress scans your content and finds a synonym, it will act as if it has found the main term.'=>'Wenn TaxoPress Ihren Inhalt scannt und ein Synonym findet, wird es so behandelt, als hätte es den Hauptbegriff gefunden.','This synonym can\'t be added because %1$s is a term on this site.'=>'Dieses Synonym kann nicht hinzugefügt werden, da %1$s ein Begriff auf dieser Seite ist.','These synonyms can\'t be added because %1$s are terms on this site.'=>'Diese Synonyme können nicht hinzugefügt werden, da %1$s Begriffe auf dieser Seite sind.','This synonym can\'t be added because %1$s is already added to another term.'=>'Dieses Synonym kann nicht hinzugefügt werden, da %1$s bereits einem anderen Begriff hinzugefügt wurde.','These synonyms can\'t be added because %1$s are already added to another term.'=>'Diese Synonyme können nicht hinzugefügt werden, da %1$s bereits einem anderen Begriff hinzugefügt wurden.','%1$s can\'t be added as a tag because %2$s is already used as a synonym.'=>'%1$s kann nicht als Tag hinzugefügt werden, da %2$s bereits als Synonym verwendet wird.','Request status.'=>'Anforderungsstatus.','Security error. Kindly reload this page and try again'=>'Sicherheitsfehler. Bitte laden Sie diese Seite neu und versuchen Sie es erneut.','Default'=>'Standard','Dropdown'=>'Dropdown','Checkbox'=>'Checkbox','Taxonomy Display'=>'Taxonomie Anzeige','Enable IBM Watson integration'=>'IBM Watson-Integration aktivieren','Show IBM Watson as an AI source for Auto Terms'=>'IBM Watson als KI-Quelle für Auto-Begriffe anzeigen','Enable Dandelion integration'=>'Dandelion-Integration aktivieren','Show Dandelion as an AI source for Auto Terms.'=>'Dandelion als KI-Quelle für Auto-Begriffe anzeigen.','Enable LSEG/Refinitiv integration'=>'LSEG/Refinitiv-Integration aktivieren','Show LSEG/Refinitiv as an AI source for Auto Terms'=>'LSEG/Refinitiv als KI-Quelle für Auto-Begriffe anzeigen','Term successfully copied with metadata.'=>'Begriff erfolgreich mit Metadaten kopiert.','Copy with Metadata'=>'Kopieren mit Metadaten']];